import { useEffect, useRef, useState } from 'react';
import { X, RotateCcw, Send } from 'lucide-react';
import {
  StyledWidget,
  StyledWidgetHeader,
  StyledWidgetAvatar,
  StyledWidgetLogoBadge,
  StyledWidgetHeaderText,
  StyledWidgetName,
  StyledWidgetNameSub,
  StyledWidgetStatus,
  StyledHeaderIconBtn,
  StyledMessageList,
  StyledWidgetInput,
  StyledFakeInput,
  StyledSendBtn,
} from './styles';
import {
  INTRO_SCRIPT,
  SCENARIOS,
  type Scenario,
  type ScriptStep,
} from './script';
import { MessageBubble } from './MessageBubble';
import { TypingIndicator } from './TypingIndicator';
import { CtaCard } from './CtaCard';
import { ScenarioChips } from './ScenarioChips';
import { TipaLogo } from './TipaLogo';

interface ChatbotWidgetProps {
  exiting: boolean;
  onClose: () => void;
  onCtaClick: () => void;
}

type RenderedItem =
  | {
      kind: 'ai' | 'user';
      text: string;
      typingMs: number;
      instant?: boolean;
      key: string;
    }
  | { kind: 'chips'; hideIds: string[]; key: string }
  | { kind: 'cta'; key: string };

export function ChatbotWidget({ exiting, onClose, onCtaClick }: ChatbotWidgetProps) {
  const [items, setItems] = useState<RenderedItem[]>([]);
  const [showTyping, setShowTyping] = useState(false);
  const [runId, setRunId] = useState(0);
  const [answeredIds, setAnsweredIds] = useState<string[]>([]);
  const listRef = useRef<HTMLDivElement | null>(null);
  const timersRef = useRef<number[]>([]);
  const seqRef = useRef(0);

  const scrollToBottom = () => {
    const el = listRef.current;
    if (!el) return;
    requestAnimationFrame(() => {
      el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' });
    });
  };

  const clearTimers = () => {
    timersRef.current.forEach((id) => window.clearTimeout(id));
    timersRef.current = [];
  };

  const schedule = (fn: () => void, ms: number) => {
    const id = window.setTimeout(fn, ms);
    timersRef.current.push(id);
  };

  const playSteps = (steps: ScriptStep[], answeredSoFar: string[], onFinish?: () => void) => {
    let cursor = 0;

    const next = () => {
      if (cursor >= steps.length) {
        onFinish?.();
        return;
      }
      const step = steps[cursor];

      schedule(() => {
        if (step.kind === 'ai') {
          if (step.instant) {
            setItems((prev) => [
              ...prev,
              {
                kind: 'ai',
                text: step.text,
                typingMs: step.typingMs,
                instant: true,
                key: `ai-${runId}-${seqRef.current++}`,
              },
            ]);
            scrollToBottom();
            schedule(() => {
              cursor += 1;
              next();
              scrollToBottom();
            }, 400);
            return;
          }
          setShowTyping(true);
          scrollToBottom();
          schedule(() => {
            setShowTyping(false);
            setItems((prev) => [
              ...prev,
              {
                kind: 'ai',
                text: step.text,
                typingMs: step.typingMs,
                key: `ai-${runId}-${seqRef.current++}`,
              },
            ]);
            scrollToBottom();
            schedule(() => {
              cursor += 1;
              next();
              scrollToBottom();
            }, step.typingMs + 250);
          }, 700);
        } else if (step.kind === 'user') {
          setItems((prev) => [
            ...prev,
            {
              kind: 'user',
              text: step.text,
              typingMs: step.typingMs,
              key: `user-${runId}-${seqRef.current++}`,
            },
          ]);
          scrollToBottom();
          schedule(() => {
            cursor += 1;
            next();
            scrollToBottom();
          }, step.typingMs + 250);
        } else if (step.kind === 'chips') {
          setItems((prev) => [
            ...prev,
            {
              kind: 'chips',
              hideIds: answeredSoFar,
              key: `chips-${runId}-${seqRef.current++}`,
            },
          ]);
          scrollToBottom();
          cursor += 1;
        } else {
          // cta
          setItems((prev) => [...prev, { kind: 'cta', key: `cta-${runId}-${seqRef.current++}` }]);
          scrollToBottom();
          cursor += 1;
        }
      }, step.delayBeforeMs);
    };

    next();
  };

  // 초기 인트로 재생
  useEffect(() => {
    clearTimers();
    setItems([]);
    setShowTyping(false);
    setAnsweredIds([]);
    seqRef.current = 0;

    playSteps(INTRO_SCRIPT, []);

    return () => {
      clearTimers();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [runId]);

  const handleSelectScenario = (scenario: Scenario) => {
    clearTimers();
    // 가장 최근 chips 제거 (선택됐으니)
    setItems((prev) => {
      const copy = [...prev];
      for (let i = copy.length - 1; i >= 0; i--) {
        if (copy[i].kind === 'chips') {
          copy.splice(i, 1);
          break;
        }
      }
      return copy;
    });

    const nextAnswered = [...answeredIds, scenario.id];
    setAnsweredIds(nextAnswered);

    const allAnswered = nextAnswered.length >= SCENARIOS.length;
    // 마지막 chips 단계는 모두 답했으면 CTA로 대체
    const stepsToPlay: ScriptStep[] = scenario.steps.map((step) => {
      if (step.kind === 'chips' && allAnswered) {
        return { kind: 'cta', delayBeforeMs: step.delayBeforeMs };
      }
      return step;
    });

    playSteps(stepsToPlay, nextAnswered);
  };

  const handleRestart = () => {
    clearTimers();
    setRunId((r) => r + 1);
  };

  return (
    <StyledWidget $exiting={exiting}>
      <StyledWidgetHeader>
        <StyledWidgetAvatar>
          <StyledWidgetLogoBadge>
            <TipaLogo />
          </StyledWidgetLogoBadge>
        </StyledWidgetAvatar>
        <StyledWidgetHeaderText>
          <StyledWidgetName>
            <span>TIPA</span>
            <StyledWidgetNameSub>NI</StyledWidgetNameSub>
          </StyledWidgetName>
          <StyledWidgetStatus>온라인</StyledWidgetStatus>
        </StyledWidgetHeaderText>
        <StyledHeaderIconBtn onClick={handleRestart} aria-label="다시 보기">
          <RotateCcw size={16} />
        </StyledHeaderIconBtn>
        <StyledHeaderIconBtn onClick={onClose} aria-label="닫기">
          <X size={18} />
        </StyledHeaderIconBtn>
      </StyledWidgetHeader>

      <StyledMessageList ref={listRef}>
        {items.map((item) => {
          if (item.kind === 'cta') {
            return <CtaCard key={item.key} onClick={onCtaClick} />;
          }
          if (item.kind === 'chips') {
            return (
              <ScenarioChips
                key={item.key}
                hideIds={item.hideIds}
                onSelect={handleSelectScenario}
              />
            );
          }
          return (
            <MessageBubble
              key={item.key}
              side={item.kind}
              text={item.text}
              typingMs={item.typingMs}
              instant={item.instant}
              onComplete={scrollToBottom}
            />
          );
        })}
        {showTyping && <TypingIndicator />}
      </StyledMessageList>

      <StyledWidgetInput>
        <StyledFakeInput>AI가 응답 중이에요...</StyledFakeInput>
        <StyledSendBtn disabled aria-label="전송">
          <Send size={16} />
        </StyledSendBtn>
      </StyledWidgetInput>
    </StyledWidget>
  );
}
