import { Fragment, useEffect, useState } from 'react';
import { StyledBubble, StyledMessageRow, StyledRichBubble } from './styles';

interface MessageBubbleProps {
  side: 'ai' | 'user';
  text: string;
  typingMs: number;
  instant?: boolean;
  onComplete?: () => void;
}

// **bold** 마크업을 <strong>으로 변환
function renderMarkup(text: string) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g);
  return parts.map((part, i) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <strong key={i}>{part.slice(2, -2)}</strong>;
    }
    return <Fragment key={i}>{part}</Fragment>;
  });
}

export function MessageBubble({ side, text, typingMs, instant, onComplete }: MessageBubbleProps) {
  const [visibleLength, setVisibleLength] = useState(instant ? text.length : 0);
  const isRich = instant || text.length > 120;

  useEffect(() => {
    if (instant) {
      setVisibleLength(text.length);
      onComplete?.();
      return;
    }

    setVisibleLength(0);
    const total = text.length;
    if (total === 0) {
      onComplete?.();
      return;
    }

    const stepMs = Math.max(10, Math.floor(typingMs / total));
    let current = 0;
    const interval = setInterval(() => {
      current += 1;
      setVisibleLength(current);
      if (current >= total) {
        clearInterval(interval);
        onComplete?.();
      }
    }, stepMs);

    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text, typingMs, instant]);

  const content = instant
    ? renderMarkup(text)
    : renderMarkup(text.slice(0, visibleLength));

  const Bubble = isRich ? StyledRichBubble : StyledBubble;

  return (
    <StyledMessageRow $side={side}>
      <Bubble $side={side}>{content}</Bubble>
    </StyledMessageRow>
  );
}
