import { SCENARIOS, type Scenario } from './script';
import {
  StyledChipsCard,
  StyledChipsTitle,
  StyledChipsList,
  StyledChip,
  StyledChipIcon,
  StyledChipLabel,
} from './styles';

interface ScenarioChipsProps {
  onSelect: (scenario: Scenario) => void;
  hideIds?: string[];
}

export function ScenarioChips({ onSelect, hideIds = [] }: ScenarioChipsProps) {
  const items = SCENARIOS.filter((s) => !hideIds.includes(s.id));
  if (items.length === 0) return null;

  return (
    <StyledChipsCard>
      <StyledChipsTitle>💬 어떤 도움이 필요하세요?</StyledChipsTitle>
      <StyledChipsList>
        {items.map((s) => (
          <StyledChip key={s.id} onClick={() => onSelect(s)}>
            <StyledChipIcon>{s.icon}</StyledChipIcon>
            <StyledChipLabel>
              <strong>{s.label}</strong>
              <span>{s.chipText}</span>
            </StyledChipLabel>
          </StyledChip>
        ))}
      </StyledChipsList>
    </StyledChipsCard>
  );
}
